language plpgsql
security definer
set search_path = public
as $$
declare
    v_hold public.holds;
    v_result jsonb := '{}'::jsonb;
begin
    -- 再送(冪等): 最初に作る行が既にあれば、以降の手順を実行せずに既存の行を返す。
    -- 再送として返すのは、実行者が作った行(patron_id = 実行者)だけ。他人の行は中身を返さず競合にする(実行者が null の呼び出しは誰の行とも一致しない)。
