        if not exists (select 1 from public.resend_digests r where r.event_id = 'usecase:hold_and_collect.place' and r.entity_id = p_id and r.created_at > now() - interval '24 hours') then
            raise exception using errcode = 'UC412', message = 'usecase_guard:' || 'hold.create', detail = 'resend_expired';
        end if;
        -- 保存点の入力の全体(正規化した p_input の要約)が 1 回目と違えば、1 回目の行を「書けた」と返さず断る。
        if not exists (select 1 from public.resend_digests r where r.event_id = 'usecase:hold_and_collect.place' and r.entity_id = p_id and r.created_at > now() - interval '24 hours' and r.input_digest = encode(sha256(convert_to(jsonb_build_object('hold.create', case when jsonb_typeof(p_input -> 'hold.create') = 'object' then jsonb_strip_nulls(p_input -> 'hold.create') else '{}'::jsonb end)::text, 'UTF8')), 'hex')) then
            raise exception using errcode = 'UC412', message = 'usecase_guard:' || 'hold.create', detail = 'resend_input_mismatch';
        end if;
        return jsonb_build_object(
            'hold.create', (select to_jsonb(t) from public.holds t where t.id = p_id)
