    end if;

    -- 錨の作成が再送だったかは、作成 RPC が同じ txn の中の印で知らせる(点検 22 回目 A22-1)。前の呼び出しの印を消す。
    perform set_config('st.resent_id', '', true);
    -- 手順 1: hold.create
    select * into v_hold from api.insert_hold(
        p_id => p_id,
        p_item_id => (p_input -> 'hold.create' ->> 'item_id')::uuid,
        p_patron_id => p_actor_id,
        p_note => p_input -> 'hold.create' ->> 'note',
        p_actor_id => p_actor_id,
        p_actor_roles => p_actor_roles
    );
    if not found then
        raise exception using errcode = 'UC409', message = 'usecase_conflict:hold.create';
    end if;
    v_result := v_result || jsonb_build_object('hold.create', to_jsonb(v_hold));
    -- 錨の作成 RPC が再送だった(先頭の確かめの後に、同じ鍵の 1 回目がコミットした)。以降の手順を実行せず、先頭の枝と同じ比べと読み直しへ。
    if current_setting('st.resent_id', true) is not distinct from p_id::text then
        if not exists (select 1 from public.resend_digests r where r.event_id = 'usecase:hold_and_collect.place' and r.entity_id = p_id and r.created_at > now() - interval '24 hours') then
            raise exception using errcode = 'UC412', message = 'usecase_guard:' || 'hold.create', detail = 'resend_expired';
        end if;
        if not exists (select 1 from public.resend_digests r where r.event_id = 'usecase:hold_and_collect.place' and r.entity_id = p_id and r.created_at > now() - interval '24 hours' and r.input_digest = encode(sha256(convert_to(jsonb_build_object('hold.create', case when jsonb_typeof(p_input -> 'hold.create') = 'object' then jsonb_strip_nulls(p_input -> 'hold.create') else '{}'::jsonb end)::text, 'UTF8')), 'hex')) then
